import 'package:flutter/material.dart';
import '../controller/app_controller.dart';
import '../models/models.dart';
class SafetyReportScreen extends StatefulWidget{const SafetyReportScreen({super.key,required this.controller,this.targetUserId,this.sourceType='other',this.sourceId});final AppController controller;final String? targetUserId,sourceId;final String sourceType;@override State<SafetyReportScreen> createState()=>_SafetyReportScreenState();}
class _SafetyReportScreenState extends State<SafetyReportScreen>{String category='Harassment or abusive behavior';final details=TextEditingController();bool sending=false;List<UserReportItem> reports=[];String? error;@override void initState(){super.initState();_load();widget.controller.trackEvent('safety_report_open');}@override void dispose(){details.dispose();super.dispose();}
Future<void> _load()async{try{final r=await widget.controller.api.get('/reports/me');reports=((r['items']as List?)??const[]).whereType<Map>().map((e)=>UserReportItem.fromJson(e.cast<String,dynamic>())).toList();if(mounted)setState((){});}catch(e){if(mounted)setState(()=>error='$e');}}
Future<void> _submit()async{if(details.text.trim().length<4){setState(()=>error='Please add a few details.');return;}setState(()=>sending=true);try{await widget.controller.api.post('/reports',body:{if(widget.targetUserId!=null)'targetUserId':widget.targetUserId,'sourceType':widget.sourceType,if(widget.sourceId!=null)'sourceId':widget.sourceId,'category':category,'details':details.text.trim()});details.clear();error=null;await _load();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Report submitted for review.')));}catch(e){error='$e';}finally{if(mounted)setState(()=>sending=false);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Safety & reports')),body:ListView(padding:const EdgeInsets.all(18),children:[const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Reports are reviewed by moderation. A report does not automatically ban another user. Include concrete details and avoid sharing passwords or payment information.'))),const SizedBox(height:14),DropdownButtonFormField<String>(value:category,items:const['Harassment or abusive behavior','Cheating or suspicious play','Spam','Inappropriate profile','Technical/game issue','Other'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>category=v??category),decoration:const InputDecoration(labelText:'Category')),const SizedBox(height:12),TextField(controller:details,maxLines:5,maxLength:1500,decoration:const InputDecoration(labelText:'What happened?')),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error)),FilledButton.icon(onPressed:sending?null:_submit,icon:const Icon(Icons.flag_rounded),label:Text(sending?'Submitting…':'Submit report')),const SizedBox(height:24),Text('Your reports',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:8),if(reports.isEmpty)const Text('No reports submitted from this account.'),...reports.map((r)=>Card(child:ListTile(title:Text(r.category),subtitle:Text('${r.status} • ${r.createdAt.toLocal()}${r.resolutionNote==null?'':'\n${r.resolutionNote}'}'),isThreeLine:r.resolutionNote!=null))) ]));}
